INSERT IGNORE INTO traffic_signs (id, name, category, description, image_path, safety_instruction) VALUES
(1, 'Stop', 'MANDATORY', 'You must stop completely at this point.', '/assets/signs/stop.svg', 'Halt at the stop line. Go only when the way is clear.'),
(2, 'No Entry', 'MANDATORY', 'Vehicles may not enter this road from this side.', '/assets/signs/noEntry.svg', 'Do not enter. Find another route.'),
(3, 'No Parking', 'MANDATORY', 'You may not leave your vehicle parked here.', '/assets/signs/noParking.svg', 'Park only in a marked parking area.'),
(4, 'Speed Limit', 'MANDATORY', 'The number shows the highest speed allowed, in km/h.', '/assets/signs/speed.svg', 'Keep at or below the limit. Slow down more in bad weather.'),
(5, 'One Way', 'MANDATORY', 'Traffic moves only in the direction of the arrow.', '/assets/signs/oneWay.svg', 'Drive the arrow way only. Never go against it.'),
(6, 'No Horn', 'MANDATORY', 'Horns are not allowed here, often near hospitals and schools.', '/assets/signs/noHorn.svg', 'Keep your horn silent. Slow down and stay alert.'),
(7, 'No U-Turn', 'MANDATORY', 'You may not turn around to go back the way you came.', '/assets/signs/noUturn.svg', 'Go ahead and use a permitted turning point.'),
(8, 'Compulsory Turn Left', 'MANDATORY', 'Vehicles must turn left at this point.', '/assets/signs/turnLeft.svg', 'Get in the left lane early and turn left.'),
(9, 'School Ahead', 'CAUTIONARY', 'A school is near. Children may cross suddenly.', '/assets/signs/school.svg', 'Slow down, be ready to stop, and give way to children.'),
(10, 'Pedestrian Crossing', 'CAUTIONARY', 'People may be crossing the road ahead.', '/assets/signs/crossing.svg', 'Slow down and stop for anyone on the crossing.'),
(11, 'Sharp Turn', 'CAUTIONARY', 'The road bends sharply ahead.', '/assets/signs/sharpTurn.svg', 'Slow down before the bend. Do not overtake.'),
(12, 'Narrow Road', 'CAUTIONARY', 'The road becomes narrower ahead.', '/assets/signs/narrow.svg', 'Slow down and give way to oncoming traffic.'),
(13, 'Speed Breaker', 'CAUTIONARY', 'A raised hump on the road is ahead.', '/assets/signs/breaker.svg', 'Slow down so you can cross it smoothly.'),
(14, 'Railway Crossing', 'CAUTIONARY', 'A railway line crosses the road ahead.', '/assets/signs/railway.svg', 'Slow down, look both ways and never cross when the barrier is down.'),
(15, 'Slippery Road', 'CAUTIONARY', 'The road can be slippery, especially when wet.', '/assets/signs/slippery.svg', 'Drive slowly and brake gently.'),
(16, 'Road Work Ahead', 'CAUTIONARY', 'Workers or machines may be on the road.', '/assets/signs/roadwork.svg', 'Slow down, follow the cones and watch for workers.'),
(17, 'Hospital', 'INFORMATORY', 'A hospital is nearby.', '/assets/signs/hospital.svg', 'Keep noise low and make way for ambulances.'),
(18, 'Petrol Pump', 'INFORMATORY', 'Fuel is available ahead.', '/assets/signs/petrol.svg', 'Indicate early and slow down before turning in.'),
(19, 'Parking', 'INFORMATORY', 'You may park here.', '/assets/signs/parking.svg', 'Park neatly inside the marked area.'),
(20, 'Bus Stop', 'INFORMATORY', 'Buses stop here for passengers.', '/assets/signs/busStop.svg', 'Do not park here. Watch for people boarding.'),
(21, 'First Aid', 'INFORMATORY', 'A first aid post is nearby.', '/assets/signs/firstAid.svg', 'Note the place in case you or someone needs help.'),
(22, 'Rest Area', 'INFORMATORY', 'A place to stop and rest is ahead.', '/assets/signs/rest.svg', 'Take a break if you feel tired. Tired driving is risky.');
INSERT IGNORE INTO quiz_questions (id, question_text, category, difficulty, correct_option, explanation) VALUES
(1, 'Which is a common cause of road accidents?', 'BASICS', 'EASY', 3, 'Higher speed leaves less time to react.'),
(2, 'What should you do before starting a journey?', 'BASICS', 'EASY', 2, 'A quick check of brakes, tyres and lights prevents breakdowns.'),
(3, 'Why should you keep a safe distance from the vehicle ahead?', 'BASICS', 'MEDIUM', 2, 'A gap gives you time and space to react.'),
(4, 'What is the safest way to deal with tiredness on a long drive?', 'BASICS', 'HARD', 0, 'Only rest cures tiredness. Fatigue slows your reactions.'),
(5, 'Who must follow traffic rules?', 'TRAFFIC_RULES', 'EASY', 0, 'Rules apply to all road users.'),
(6, 'Is it safe to use a mobile phone while riding a two-wheeler?', 'TRAFFIC_RULES', 'MEDIUM', 1, 'Phones take your eyes and hands away from controlling the vehicle.'),
(7, 'Why should you use your indicator?', 'TRAFFIC_RULES', 'MEDIUM', 1, 'Indicators let others predict your move.'),
(8, 'When is it safe to overtake?', 'TRAFFIC_RULES', 'HARD', 2, 'Overtaking needs a clear view. Never overtake on bends, crests or crossings.'),
(9, 'When should a two-wheeler rider wear a helmet?', 'HELMET_SEATBELT', 'EASY', 1, 'Crashes happen on short trips as well.'),
(10, 'Who should wear a seatbelt in a car?', 'HELMET_SEATBELT', 'EASY', 2, 'Rear passengers can be thrown forward without a belt.'),
(11, 'Why must the helmet chin strap be fastened?', 'HELMET_SEATBELT', 'MEDIUM', 2, 'A helmet only protects if it stays on your head.'),
(12, 'Do airbags replace seatbelts?', 'HELMET_SEATBELT', 'MEDIUM', 1, 'Airbags are designed to work together with seatbelts.'),
(13, 'Where should the lap part of a seatbelt sit?', 'HELMET_SEATBELT', 'HARD', 1, 'A low, snug lap belt protects the strong hip bones.'),
(14, 'Where is the safest place to cross the road?', 'PEDESTRIAN_SAFETY', 'EASY', 1, 'Drivers expect people at crossings.'),
(15, 'What do you do first before crossing?', 'PEDESTRIAN_SAFETY', 'EASY', 1, 'Look right, left, then right again.'),
(16, 'A school bus has stopped. What should children do?', 'PEDESTRIAN_SAFETY', 'MEDIUM', 3, 'Drivers cannot see people close behind or in front of a bus.'),
(17, 'How can you stay visible while walking at night?', 'PEDESTRIAN_SAFETY', 'HARD', 1, 'Reflective items help drivers notice you earlier.'),
(18, 'What does a red traffic light mean?', 'SIGNALS_SIGNS', 'EASY', 3, 'Stop behind the stop line.'),
(19, 'What shape are mandatory signs usually?', 'SIGNALS_SIGNS', 'EASY', 1, 'Mandatory signs are mostly circular with a red border.'),
(20, 'What does a yellow light tell you?', 'SIGNALS_SIGNS', 'MEDIUM', 2, 'Yellow is a warning that red is coming.'),
(21, 'A traffic police officer signals you to stop while the light is green. What do you do?', 'SIGNALS_SIGNS', 'HARD', 1, 'Directions from a traffic police officer overrule the signal.'),
(22, 'Which number do you call for emergency help in India?', 'EMERGENCY', 'EASY', 0, '112 is the national emergency number.'),
(23, 'What should you do if you see an accident?', 'EMERGENCY', 'MEDIUM', 0, 'Safety and a quick call for help come first.'),
(24, 'Should you move a seriously injured person?', 'EMERGENCY', 'HARD', 1, 'Moving a badly hurt person can make injuries worse. Wait for trained responders.'),
(25, 'Which headlights should you use for normal night driving?', 'CONDITIONS', 'EASY', 1, 'Dipped headlights light the road without dazzling other drivers.'),
(26, 'What should you do with your speed at night?', 'CONDITIONS', 'EASY', 2, 'Darkness shortens how far you can see, so you need more time to react.'),
(27, 'What is a good habit when you walk near a road at night?', 'CONDITIONS', 'EASY', 1, 'Bright or reflective items help drivers notice you earlier.'),
(28, 'What does a closed railway barrier mean?', 'CONDITIONS', 'EASY', 3, 'A train cannot stop quickly. Never cross when the barrier is down.'),
(29, 'Why should you avoid sudden braking on a wet road?', 'CONDITIONS', 'MEDIUM', 2, 'Wet roads give less grip, so brake early and gently.'),
(30, 'What is the safest way to drive in fog?', 'CONDITIONS', 'MEDIUM', 1, 'High beams reflect off fog. Low speed and low beams give you time and visibility.'),
(31, 'Where should you park?', 'CONDITIONS', 'MEDIUM', 2, 'Crossings, footpaths and bends must stay clear for walkers and for visibility.'),
(32, 'What should you do near a school?', 'CONDITIONS', 'MEDIUM', 3, 'Children can step out suddenly. Be ready to stop.'),
(33, 'How often should you take a break on a long highway trip?', 'CONDITIONS', 'HARD', 2, 'Regular rests keep you alert and cut the risk of tired-driving crashes.'),
(34, 'What should you do if the fog is too thick to drive safely?', 'CONDITIONS', 'HARD', 2, 'Never stop on the carriageway. Move off the road and wait.'),
(35, 'Which number can you call for help on a national highway?', 'CONDITIONS', 'HARD', 0, '1033 is the National Highway helpline. For emergencies you can also call 112.'),
(36, 'Why must you never go around a lowered railway barrier?', 'CONDITIONS', 'HARD', 2, 'Trains need a long distance to stop, so the risk is far too high.'),
(37, 'What should you do before helping a person who is blind to cross?', 'INCLUSIVE_SAFETY', 'EASY', 2, 'Always ask first, then follow what the person tells you they need.'),
(38, 'Who benefits from a pedestrian ramp?', 'INCLUSIVE_SAFETY', 'EASY', 0, 'Ramps give a smooth way up and down the kerb.'),
(39, 'How should drivers treat people who cross slowly?', 'INCLUSIVE_SAFETY', 'EASY', 3, 'Some people need more time to cross, and that is fine.'),
(40, 'What is tactile paving?', 'INCLUSIVE_SAFETY', 'MEDIUM', 1, 'The raised bumps and lines can be felt with the feet or a cane.'),
(41, 'What do audio pedestrian signals do?', 'INCLUSIVE_SAFETY', 'MEDIUM', 0, 'The sound helps people who cannot see the signal.'),
(42, 'Why should you not park on a footpath?', 'INCLUSIVE_SAFETY', 'MEDIUM', 1, 'Footpaths must stay clear so everyone can pass safely.'),
(43, 'If you offer your arm to a person who is blind, what is right?', 'INCLUSIVE_SAFETY', 'HARD', 2, 'Let the person choose how to be guided. Never grab or pull.'),
(44, 'What should you do with tactile paving?', 'INCLUSIVE_SAFETY', 'HARD', 3, 'Blocking it can leave a person with low vision without a safe path.'),
(45, 'Why are vehicle blind spots dangerous for walkers?', 'PEDESTRIAN_SAFETY', 'MEDIUM', 1, 'Stay clear of the front, back and sides of big vehicles.'),
(46, 'You reach a railway crossing and the barrier is up. What should you do?', 'PEDESTRIAN_SAFETY', 'MEDIUM', 3, 'Barriers can go down quickly. Stay alert and never stop on the tracks.'),
(47, 'A green walking signal turns on. What is the safest next step?', 'PEDESTRIAN_SAFETY', 'HARD', 3, 'The signal helps, but always check that vehicles have really stopped.'),
(48, 'What does a stop line on the road tell you?', 'SIGNALS_SIGNS', 'MEDIUM', 0, 'Stop behind the line so walkers can use the crossing.'),
(49, 'What does a solid line along the centre of the road usually mean?', 'SIGNALS_SIGNS', 'MEDIUM', 3, 'A solid line warns that overtaking is not safe or not allowed there.'),
(50, 'Which sign shape usually means “be careful”?', 'SIGNALS_SIGNS', 'HARD', 1, 'Cautionary signs are generally triangles with a red border.'),
(51, 'What does a blue rectangular sign usually give?', 'SIGNALS_SIGNS', 'HARD', 2, 'Informatory signs are mostly blue rectangles.'),
(52, 'Why is wrong-side driving dangerous?', 'BASICS', 'MEDIUM', 3, 'Head-on crashes are very serious. Always drive on your own side.'),
(53, 'Which action best reduces the risk of a crash?', 'BASICS', 'HARD', 2, 'Most crashes can be avoided by safe habits, not by luck or safety gear alone.'),
(54, 'Why is triple riding on a two-wheeler unsafe?', 'TRAFFIC_RULES', 'MEDIUM', 3, 'Two-wheelers are made for the rider and one pillion at most.'),
(55, 'What should a cyclist use after dark?', 'TRAFFIC_RULES', 'HARD', 0, 'Lights and reflectors help drivers see you.'),
(56, 'What is the best way to check a helmet fits?', 'HELMET_SEATBELT', 'MEDIUM', 2, 'A snug, level helmet with a fastened strap protects best.'),
(57, 'Should a helmet be replaced after a hard impact?', 'HELMET_SEATBELT', 'HARD', 2, 'A hard hit can weaken the helmet even when it looks fine.'),
(58, 'What information should you give when you call 112?', 'EMERGENCY', 'MEDIUM', 0, 'Clear location and details help responders reach the place fast.'),
(59, 'Where should you stand when you stop to help at a crash?', 'EMERGENCY', 'EASY', 1, 'Your own safety comes first.');
