INSERT IGNORE INTO safety_tips (id, title, description, category, image_path) VALUES
(1, 'Helmet on, every ride', 'Always wear a properly fitted helmet, even for short journeys.', 'HELMET', '/assets/characters/arjun.svg'),
(2, 'Cross at the zebra', 'Cross only at zebra crossings, and look right, left, then right again.', 'PEDESTRIAN', '/assets/characters/riya.svg'),
(3, 'Back seat needs belts too', 'Buckle up in the back seat too. Every seat needs a seatbelt.', 'SEATBELT', '/assets/characters/sam.svg'),
(4, 'Phone down, eyes up', 'Never use a phone while riding or driving. Pull over to a safe place first.', 'DRIVING', '/assets/characters/ravi.svg'),
(5, 'Keep a safe gap', 'Keep a safe gap from the vehicle ahead so you have time to stop.', 'DRIVING', '/assets/characters/sam.svg'),
(6, 'School bus rule', 'Wait for a school bus to stop fully before you step off or cross.', 'PEDESTRIAN', '/assets/characters/riya.svg'),
(7, 'Light up your cycle', 'Use lights and reflectors on your bicycle after sunset.', 'CYCLING', '/assets/characters/arjun.svg'),
(8, 'Yellow means get ready', 'A yellow light means get ready to stop, not speed up.', 'DRIVING', '/assets/characters/ravi.svg');
INSERT IGNORE INTO awareness_campaigns (id, title, description, start_date, end_date, category, poster_path) VALUES
