(2, 'Helmet Awareness Drive', 'Volunteers speak with riders about wearing a certified, well-fitted helmet and fastening the strap.', '2026-12-01', '2026-12-07', 'HELMET', '/assets/posters/campaign-2.svg'),
(3, 'Pedestrian Safety Walk', 'Students walk through local crossings with banners that show how to cross safely.', '2026-10-02', '2026-10-09', 'PEDESTRIAN', '/assets/posters/campaign-3.svg'),
(4, 'School Road Safety Programme', 'Short sessions for children on school bus rules, safe crossing and reading signs.', '2027-01-20', '2027-01-22', 'SCHOOL', '/assets/posters/campaign-4.svg'),
(5, 'Poster Competition', 'Draw a poster that shows one safe road habit. Use bold colours and a short message.', '2027-02-01', '2027-02-14', 'COMPETITION', '/assets/posters/campaign-5.svg'),
